/**
 * The harness: never in a shipped app, a link only on the loopback interface, and the protocol the
 * acceptance world speaks to both desktop hosts.
 */
import { EventEmitter, once } from 'events';
import net from 'net';
import { matchesGlob } from 'path';
import { createInterface } from 'readline';
import { describe, expect, it, vi } from 'vitest';

import { holochainArgs, linkAddress, startHarness } from './harness.js';

// The package's resource list is generated by a build; the file list under test is not.
vi.mock('fs', async (importOriginal) => {
  const fs = await importOriginal();
  const readFileSync = (path, ...rest) =>
    String(path).endsWith('seed-extra-resources.json') ? '[]' : fs.readFileSync(path, ...rest);
  return { ...fs, readFileSync, default: { ...fs, readFileSync } };
});

/** Whether electron-builder's `files` patterns, read in order as it reads them, take `file`. */
function packs(patterns, file) {
  let taken = false;
  for (const pattern of patterns) {
    if (pattern.startsWith('!')) {
      if (matchesGlob(file, pattern.slice(1))) taken = false;
    } else if (matchesGlob(file, pattern)) taken = true;
  }
  return taken;
}

const LINK = { COASYS_HARNESS_URL: 'tcp://127.0.0.1:4000', COASYS_HARNESS_TOKEN: 'token' };

describe('a shipped app cannot be driven', () => {
  it('the package leaves the harness out', async () => {
    const { default: config } = await import('../electron-builder.config.js');
    expect(packs(config.files, 'electron/main.js')).toBe(true);
    expect(packs(config.files, 'electron/harness.js')).toBe(false);
  });

  it('a packaged app does not start it, link or not', () => {
    const connect = vi.fn();
    const ipcMain = { handle: vi.fn() };
    const handle = ipcMain.handle;
    const socket = startHarness({
      app: { isPackaged: true },
      ipcMain,
      windows: () => ({}),
      custodyState: async () => ({}),
      env: LINK,
      connect,
    });
    expect(socket).toBeNull();
    expect(connect).not.toHaveBeenCalled();
    expect(ipcMain.handle).toBe(handle);
  });
});

describe('linkAddress', () => {
  it('answers no link when none is named', () => {
    expect(linkAddress({})).toBeNull();
  });

  it('takes a link on the loopback interface and refuses any other', () => {
    expect(linkAddress(LINK)).toEqual({ host: '127.0.0.1', port: 4000 });
    expect(linkAddress({ COASYS_HARNESS_URL: 'tcp://[::1]:4000' })).toEqual({ host: '::1', port: 4000 });
    expect(() => linkAddress({ COASYS_HARNESS_URL: 'tcp://10.0.0.5:4000' })).toThrow(/loopback/);
    expect(() => linkAddress({ COASYS_HARNESS_URL: 'tcp://example.com:4000' })).toThrow(/loopback/);
    expect(() => linkAddress({ COASYS_HARNESS_URL: '8.8.8.8:4000' })).toThrow();
  });

  it('refuses a link off the loopback interface before connecting', () => {
    const connect = vi.fn();
    const quiet = vi.spyOn(console, 'error').mockImplementation(() => {});
    const socket = startHarness({
      app: { isPackaged: false },
      ipcMain: { handle: vi.fn() },
      windows: () => ({}),
      custodyState: async () => ({}),
      env: { COASYS_HARNESS_URL: 'tcp://10.0.0.5:4000' },
      connect,
    });
    quiet.mockRestore();
    expect(socket).toBeNull();
    expect(connect).not.toHaveBeenCalled();
  });
});

describe('holochainArgs', () => {
  it('runs without Holochain unless asked', () => {
    expect(holochainArgs({})).toEqual(['--run-holochain', 'false', '--connect-holochain', 'false']);
    expect(holochainArgs({ COASYS_HARNESS_HOLOCHAIN: 'on' })).toEqual(['--connect-holochain', 'true']);
  });
});

describe('the protocol', () => {
  it('says hello with the token, and answers eval, state and ipc.log', async () => {
    const server = net.createServer();
    server.listen(0, '127.0.0.1');
    await once(server, 'listening');
    const accepted = once(server, 'connection');

    /** A window's contents: a script that presses "Done" closes the window before it answers. */
    const page = (url) => {
      const contents = new EventEmitter();
      let destroyed = false;
      return Object.assign(contents, {
        getURL: () => url,
        isDestroyed: () => destroyed,
        executeJavaScript: (code) => {
          if (code.includes('Done')) {
            destroyed = true;
            contents.emit('destroyed');
            return new Promise(() => {});
          }
          expect(code).toContain('return 1 + 1;');
          return Promise.resolve(JSON.stringify({ two: 2 }));
        },
      });
    };
    const main = { isDestroyed: () => false, webContents: page('http://localhost:9080/') };
    const identity = {
      isDestroyed: () => identity.webContents.isDestroyed(),
      webContents: page('we-identity://window/'),
    };
    const handlers = new Map();
    const ipcMain = { handle: (channel, handler) => handlers.set(channel, handler) };
    const app = startHarness({
      app: { isPackaged: false },
      ipcMain,
      windows: () => ({ main, identity }),
      custodyState: async () => ({ did: 'did:example' }),
      env: { COASYS_HARNESS_URL: `tcp://127.0.0.1:${server.address().port}`, COASYS_HARNESS_TOKEN: 'token' },
    });

    ipcMain.handle('identity-open', (_event, step) => step.kind);
    expect(handlers.get('identity-open')({ sender: main.webContents }, { kind: 'create', words: 'secret' })).toBe(
      'create',
    );

    const [socket] = await accepted;
    const lines = createInterface({ input: socket })[Symbol.asyncIterator]();
    const next = async () => JSON.parse((await lines.next()).value);
    expect(await next()).toMatchObject({ hello: 'we', token: 'token' });

    socket.write(`${JSON.stringify({ id: 1, cmd: 'eval', args: { window: 'main', js: 'return 1 + 1;' } })}\n`);
    expect(await next()).toEqual({ id: 1, ok: true, result: { two: 2 } });
    socket.write(`${JSON.stringify({ id: 2, cmd: 'state' })}\n`);
    expect(await next()).toEqual({
      id: 2,
      ok: true,
      result: {
        windows: [
          { label: 'main', url: 'http://localhost:9080/' },
          { label: 'identity', url: 'we-identity://window/' },
        ],
        custody: { did: 'did:example' },
      },
    });
    socket.write(`${JSON.stringify({ id: 3, cmd: 'ipc.log', args: { since: 0 } })}\n`);
    const log = await next();
    expect(log.result).toEqual([{ at: expect.any(Number), window: 'main', command: 'identity-open' }]);
    expect(JSON.stringify(log)).not.toContain('secret');
    socket.write(`${JSON.stringify({ id: 4, cmd: 'eval', args: { window: 'identity', js: "h.press('Done')" } })}\n`);
    expect(await next()).toEqual({
      id: 4,
      ok: false,
      error: 'the window identity closed before the script answered',
    });
    socket.write(`${JSON.stringify({ id: 5, cmd: 'eval', args: { window: 'identity', js: '' } })}\n`);
    expect(await next()).toEqual({ id: 5, ok: false, error: 'no window identity' });

    app.destroy();
    socket.destroy();
    server.close();
  });
});
